export default "import curry from '../composition/curry';\n\ntype UniqBy = {\n  <T>(...args: [fn: (value: T) => any]): (arr: readonly T[]) => T[];\n  <T>(...args: [fn: (value: T) => any, arr: readonly T[]]): T[];\n};\n\n/**\n * uniqBy - 기준 함수로 중복 제거\n */\nfunction uniqBy<T>(fn: (value: T) => any, arr: readonly T[]): T[] {\n  const seen = new Set<any>();\n  const result: T[] = [];\n  for (const item of arr) {\n    const key = fn(item);\n    if (!seen.has(key)) {\n      seen.add(key);\n      result.push(item);\n    }\n  }\n  return result;\n}\n\nconst curriedUniqBy = curry(uniqBy) as UniqBy;\nexport default curriedUniqBy;\n"