export default "/**\n * from - 입력을 무시하고 고정 값을 반환\n */\nexport type FromFn<T> = {\n  <I>(_input: I): T;\n  readonly __from: true;\n};\n\nfunction from<T>(value: T): FromFn<T> {\n  const fn = (_input: unknown) => value;\n  Object.defineProperty(fn, '__from', { value: true });\n  return fn as FromFn<T>;\n}\n\nexport default from;\n"