export default "/**\n * mergeAll - 객체 배열 병합 (얕은 병합)\n */\nfunction mergeAll<T extends object>(objects: T[]): T {\n  const merged = objects.reduce<Record<string, unknown>>(\n    (acc, obj) => ({ ...acc, ...(obj as Record<string, unknown>) }),\n    {}\n  );\n  return merged as T;\n}\n\nexport default mergeAll;\n"