export default "import curry from '../composition/curry';\n\ntype Throttle = {\n  <T extends (...args: any[]) => any>(...args: [fn: T]): (ms: number) => T;\n  <T extends (...args: any[]) => any>(...args: [fn: T, ms: number]): T;\n};\n\n/** throttle - 호출 제어 (쓰로틀) */\nfunction throttle<T extends (...args: any[]) => any>(fn: T, ms: number): T {\n  let lastCall = 0;\n  let trailingArgs: any[] | null = null;\n  let timeoutId: ReturnType<typeof setTimeout> | null = null;\n\n  const invoke = (ctx: any, args: any[]) => {\n    lastCall = Date.now();\n    fn.apply(ctx, args);\n  };\n\n  const throttled = function (this: any, ...args: any[]) {\n    const now = Date.now();\n    const remaining = ms - (now - lastCall);\n\n    if (remaining <= 0) {\n      if (timeoutId) {\n        clearTimeout(timeoutId);\n        timeoutId = null;\n      }\n      trailingArgs = null;\n      invoke(this, args);\n    } else {\n      trailingArgs = args;\n      if (!timeoutId) {\n        timeoutId = setTimeout(() => {\n          timeoutId = null;\n          if (trailingArgs) {\n            invoke(this, trailingArgs);\n            trailingArgs = null;\n          }\n        }, remaining);\n      }\n    }\n  } as T;\n\n  return throttled;\n}\nconst curriedThrottle = curry(throttle) as Throttle;\nexport default curriedThrottle;\n"