export default "/**\n * once - 한 번만 실행되는 함수\n */\ntype AnyFn = (...args: any[]) => any;\n\nfunction once<T extends AnyFn>(fn: T): T {\n  let called = false;\n  let value: any;\n\n  const wrapped = function (this: any, ...args: any[]) {\n    if (!called) {\n      called = true;\n      value = fn.apply(this, args);\n    }\n    return value;\n  };\n\n  return wrapped as T;\n}\n\nexport default once;\n"