export default "import curry from '../composition/curry';\n\ntype Timeout = {\n  (ms: number): <T>(promise: Promise<T>) => Promise<T>;\n  <T>(...args: [ms: number, promise: Promise<T>]): Promise<T>;\n};\n\n/** timeout - 제한 시간 내 실행 */\nfunction timeout<T>(ms: number, promise: Promise<T>): Promise<T> {\n  return new Promise<T>((resolve, reject) => {\n    const timer = setTimeout(() => reject(new Error(`Timed out after ${ms}ms`)), ms);\n    promise\n      .then((val) => {\n        clearTimeout(timer);\n        resolve(val);\n      })\n      .catch((err) => {\n        clearTimeout(timer);\n        reject(err);\n      });\n  });\n}\nconst curriedTimeout = curry(timeout) as Timeout;\nexport default curriedTimeout;\n"