export default "import curry from '../composition/curry';\n\ntype AssocKey = string | number | symbol;\n\ntype AssocValue<T, K extends AssocKey, V> = K extends keyof T\n  ? (T[K] extends V ? T : Omit<T, K> & Record<K, V>)\n  : T & Record<K, V>;\n\ntype AssocResult<T, K extends AssocKey, V> =\n  T extends readonly (infer U)[]\n    ? K extends number | `${number}`\n      ? Array<V | U>\n      : AssocValue<T, K, V>\n    : AssocValue<T, K, V>;\n\ntype Assoc = {\n  <K extends AssocKey>(...args: [key: K]): <V>(value: V) => <T>(obj: T) => AssocResult<T, K, V>;\n  <K extends AssocKey, V>(...args: [key: K, value: V]): <T>(obj: T) => AssocResult<T, K, V>;\n  <T, K extends AssocKey, V>(...args: [key: K, value: V, obj: T]): AssocResult<T, K, V>;\n};\n\n/**\n * assoc - 불변 객체 속성 설정\n */\nfunction assoc<T, K extends AssocKey, V>(key: K, value: V, obj: T): AssocResult<T, K, V> {\n  if (Array.isArray(obj)) {\n    const result = obj.slice();\n    (result as any)[key] = value;\n    return result as AssocResult<T, K, V>;\n  }\n\n  if (obj && typeof obj === 'object') {\n    return {\n      ...(obj as object),\n      [key]: value,\n    } as AssocResult<T, K, V>;\n  }\n\n  return { [key]: value } as AssocResult<T, K, V>;\n}\n\nconst curriedAssoc = curry(assoc) as Assoc;\nexport default curriedAssoc;\n"