export default "import curry from '../composition/curry';\n\ntype Append = {\n  <T>(...args: [value: T]): (arr: readonly T[]) => T[];\n  <T>(...args: [value: T, arr: readonly T[]]): T[];\n};\n\n/**\n * append - 배열 끝에 값 추가\n */\nfunction append<T>(value: T, arr: readonly T[]): T[] {\n  return [...arr, value];\n}\n\nconst curriedAppend = curry(append) as Append;\nexport default curriedAppend;\n"