export default "/**\n * hasPath - 깊은 경로 존재 확인\n */\nfunction hasPath(pathArray: string[]): (obj: any) => boolean {\n  return (obj: any) => {\n    let current = obj;\n    for (const key of pathArray) {\n      if (current == null || !Object.prototype.hasOwnProperty.call(current, key)) {\n        return false;\n      }\n      current = current[key];\n    }\n    return true;\n  };\n}\n\nexport default hasPath;\n"