export default "/**\n * uniq - 중복 제거\n */\nfunction uniq<T>(arr: readonly T[]): T[] {\n  const seen = new Set<T>();\n  const result: T[] = [];\n  for (const item of arr) {\n    if (!seen.has(item)) {\n      seen.add(item);\n      result.push(item);\n    }\n  }\n  return result;\n}\n\nexport default uniq;\n"