export default "import curry from '../composition/curry';\n\ntype Prepend = {\n  <T>(...args: [value: T]): (arr: readonly T[]) => T[];\n  <T>(...args: [value: T, arr: readonly T[]]): T[];\n};\n\n/**\n * prepend - 배열 앞에 값 추가\n */\nfunction prepend<T>(value: T, arr: readonly T[]): T[] {\n  return [value, ...arr];\n}\n\nconst curriedPrepend = curry(prepend) as Prepend;\nexport default curriedPrepend;\n"