export default "import curry from '../composition/curry';\n\ntype Some = {\n  <T, S extends T>(...args: [predicate: (value: T) => value is S]): (arr: readonly T[]) => boolean;\n  <T, S extends T>(...args: [predicate: (value: T) => value is S, arr: readonly T[]]): boolean;\n  <T>(...args: [predicate: (value: T) => boolean]): (arr: readonly T[]) => boolean;\n  <T>(...args: [predicate: (value: T) => boolean, arr: readonly T[]]): boolean;\n};\n\n/**\n * some - 조건 검사 (하나라도 만족)\n */\nfunction some<T>(predicate: (value: T) => boolean, arr: readonly T[]): boolean {\n  for (let i = 0; i < arr.length; i++) {\n    if (predicate(arr[i])) return true;\n  }\n  return false;\n}\n\nconst curriedSome = curry(some) as Some;\nexport default curriedSome;\n"