export default "import curry from '../composition/curry';\n\ntype Map = {\n  <T, R>(...args: [fn: (value: T) => R]): (arr: readonly T[]) => R[];\n  <T, R>(...args: [fn: (value: T) => R, arr: readonly T[]]): R[];\n};\n\n/**\n * map - 요소 변환\n */\nfunction map<T, R>(fn: (value: T) => R, arr: readonly T[]): R[] {\n  return arr.map(fn);\n}\n\nconst curriedMap = curry(map) as Map;\nexport default curriedMap;\n"