export default "/**\n * unzip - 배열 분리\n */\nfunction unzip<T, U>(arr: ReadonlyArray<readonly [T, U]>): [T[], U[]] {\n  const left: T[] = [];\n  const right: U[] = [];\n\n  for (const [a, b] of arr) {\n    left.push(a);\n    right.push(b);\n  }\n\n  return [left, right];\n}\n\nexport default unzip;\n"