export default "/** maybe - null-safe 연산 */\nfunction maybe<T, R>(fn: (value: T) => R): (value: T | null | undefined) => R | null {\n  return (value: T | null | undefined) => {\n    if (value === null || value === undefined) {\n      return null;\n    }\n    return fn(value);\n  };\n}\nexport default maybe;\n"